use std::fs

fn parse_line(line: string) -> Vec<string> {
    let cs: Vec<char> = line.chars().collect()
    let mut fields: Vec<string> = []
    let mut cur: string = ""
    let mut in_q: bool = false
    let mut i: int = 0
    let n = cs.len() as int
    while i < n {
        let c = cs[i]
        if in_q {
            if c == '"' {
                if i + 1 < n && cs[i + 1] == '"' {
                    cur.push('"')
                    i += 1
                } else {
                    in_q = false
                }
            } else {
                cur.push(c)
            }
        } else if c == '"' {
            in_q = true
        } else if c == ',' {
            fields.push(cur)
            cur = ""
        } else {
            cur.push(c)
        }
        i += 1
    }
    fields.push(cur)
    fields
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let fs_ = parse_line(line)
        let parts: Vec<string> = fs_.map(|f| "[${f}]").collect()
        println("${fs_.len()}: ${parts.join("|")}")
    }
}

